{
  "filter": {
    "processDefinitionId": "{{processDefinitionId}}"
  },
  "page": {
    "limit": 20
  }
}

{
  "name": "Hospital pathway: Clinic visit completed",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "referralId": "{{referralId}}",
    "patientId": "{{patientId}}",
    "patient_name": "{{patientName}}",
    "appointmentDate": "{{today}}",
    "visitSummary": "Demo consultation completed"
  }
}

{
  "name": "Hospital pathway: Next treatment cycle due",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "referralId": "{{referralId}}",
    "patientId": "{{patientId}}",
    "patient_name": "{{patientName}}",
    "cycleNumber": 2
  }
}

{
  "name": "Hospital pathway: Patient attends a treatment cycle message",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "referralId": "{{referralId}}",
    "patientId": "{{patientId}}",
    "patient_name": "{{patientName}}",
    "attendanceDate": "{{today}}",
    "attendanceSummary": "Demo attendance"
  }
}

{
  "name": "Hospital pathway: A pathway record changes message",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "referralId": "{{referralId}}",
    "patientId": "{{patientId}}",
    "patient_name": "{{patientName}}",
    "changedRecord": "referral",
    "changeSummary": "Demo referral update"
  }
}

{
  "name": "Hospital pathway: Patient appointment preference",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "preferredClinician": "no preference",
    "preferredDate": "{{preferredDate}}",
    "contactChannel": "telephone"
  }
}

{
  "name": "Hospital pathway: Patient appointment response",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "appointmentAccepted": true
  }
}

{
  "name": "Hospital pathway: Alternative consultation date",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "alternativeAppointmentDate": "{{preferredDate}}"
  }
}

{
  "name": "Hospital pathway: Patient declines consultation",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "patientDeclineReason": "Demo patient declined"
  }
}

{
  "name": "Hospital pathway: Patient consents message",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "informedConsent": true,
    "consentDecision": "consented",
    "consentDecisionDate": "{{today}}",
    "consentNotes": "Demo consent"
  }
}

{
  "name": "Hospital pathway: Patient refuses treatment message",
  "correlationKey": "{{referralId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "informedConsent": false,
    "consentDecision": "refused",
    "consentDecisionDate": "{{today}}",
    "consentNotes": "Demo refusal"
  }
}

{
  "name": "Hospital pathway: TestResultsMessage",
  "correlationKey": "{{patientId}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "patientId": "{{patientId}}",
    "fitToContinue": "yes",
    "clinicalDecisionReason": "Demo laboratory result",
    "bloodTestSummary": "Demo values within required range"
  }
}

{
  "name": "Hospital pathway: System or external service restored",
  "correlationKey": "{{incidentReference}}",
  "timeToLive": 900000,
  "messageId": "{{$guid}}",
  "variables": {
    "incidentReference": "{{incidentReference}}",
    "restoredAt": "{{today}}",
    "restorationSummary": "Demo worklist restored"
  }
}

{
  "filter": {
    "processInstanceKey": "{{processInstanceKey}}"
  },
  "page": {
    "limit": 100
  }
}

